import { BubbleCoveGameScene } from "../scenes/bubble_cove-game-scene";
import { BubbleCovePreloadScene } from "../scenes/bubble_cove-preload-scene";
import { FishingDifficultyScene } from "../scenes/fishing-mini-game/fishing-difficulty-scene";
import { FishingMiniGameScene } from "../scenes/fishing-mini-game/fishing-mini-game-scene";
import { GameOverScene } from "../scenes/game-over-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadBubbleCoveScenes: SceneLoader = (game) => {
  game.scene.add(
    SCENE_KEYS.BUBBLE_COVE_PRELOAD_SCENE,
    BubbleCovePreloadScene,
    false,
  );
  game.scene.add(SCENE_KEYS.BUBBLE_COVE_GAME_SCENE, BubbleCoveGameScene, false);
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.add(
    SCENE_KEYS.FISHING_MINI_GAME_SCENE,
    FishingMiniGameScene,
    false,
  );
  game.scene.add(
    SCENE_KEYS.FISHING_DIFFICULTY_SCENE,
    FishingDifficultyScene,
    false,
  );
  game.scene.start(SCENE_KEYS.BUBBLE_COVE_PRELOAD_SCENE);
};
