import type * as Phaser from "phaser";
import { ASSET_KEYS } from "../common/assets";
import { STORY_FLAG } from "../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import type { DeathReason } from "../common/types";
import { Keyboard } from "../components/keyboard";
import { type Fish } from "../entities/mons/fish";
import { WaterTiles } from "../entities/terrains/water-tiles";
import { BaseGameScene } from "./base-game-scene";
import { SCENE_KEYS } from "./scene-keys";

const SHORE_TREASURE_FLAGS = [
  STORY_FLAG.shore_treasure_01,
  STORY_FLAG.shore_treasure_02,
  STORY_FLAG.shore_treasure_03,
  STORY_FLAG.shore_treasure_04,
  STORY_FLAG.shore_treasure_05,
];
const SHORE_TREASURE_FLAG_SET = new Set<string>(SHORE_TREASURE_FLAGS);

export class BubbleCoveGameScene extends BaseGameScene {
  private isFishingMiniGameActive = false;
  private waterTiles?: WaterTiles;

  constructor() {
    super(SCENE_KEYS.BUBBLE_COVE_GAME_SCENE);
  }

  protected override createLevel(): Phaser.Tilemaps.Tilemap | undefined {
    const map = super.createLevel();
    if (!map) {
      return undefined;
    }

    // Initialize water tile animations
    // See: assets/data/levels/shore/WATER_TILE_MAPPING.md for tile ID analysis
    // Map Modern_Exteriors_Complete_Tileset tile IDs to sandwater animations
    // Available animations: basic_*, inverted_*, diagonal_* (see sandwater.json)
    const waterAnimationMap: Record<number, string> = {
      55511: "basic_top_left",
      55512: "basic_top",
      55513: "basic_top_right",
      55514: "inverted_top_left",
      55515: "inverted_top_right",
      55516: "diagonal_top_left",
      55517: "diagonal_top_right",
      55687: "basic_left",
      55689: "basic_right",
      55690: "inverted_bottom_left",
      55691: "inverted_bottom_right",
      55692: "diagonal_up_left",
      55693: "diagonal_up_right",
      55863: "basic_bottom_left",
      55864: "basic_bottom",
      55865: "basic_bottom_right",
      55866: "water",
      55868: "diagonal_down_left",
      55869: "diagonal_down_right",
      56044: "diagonal_bottom_left",
      56045: "diagonal_bottom_right",
    };

    this.waterTiles = new WaterTiles(
      this,
      map,
      "Modern_Exteriors_Complete_Tileset", // Tileset name in Tiled
      ASSET_KEYS.SANDWATER, // Asset key for sandwater animations
      waterAnimationMap,
    );
    this.waterTiles.initialize();

    return map;
  }

  protected override onRoundPlayerDefeated(_deathReason: DeathReason): void {
    this.resetMarbleTreasures();
  }

  private resetMarbleTreasures(): void {
    this.dataManager.clearFlags(SHORE_TREASURE_FLAGS);

    Object.values(this.rooms).forEach((room) => {
      room.buriedTreasures.forEach((treasure) => {
        if (
          treasure.storyFlag &&
          SHORE_TREASURE_FLAG_SET.has(treasure.storyFlag)
        ) {
          treasure.isDiscoveredInHunt = false;
          treasure.resetTreasure();
        }
      });
    });

    const currentRoom = this.rooms[this.currentRoomId];
    if (!currentRoom) {
      return;
    }

    currentRoom.buriedTreasures.forEach((treasure) => {
      if (
        treasure.storyFlag &&
        SHORE_TREASURE_FLAG_SET.has(treasure.storyFlag)
      ) {
        treasure.enableObject();
      }
    });
  }

  private onEnterRoom = (roomId: number): void => {
    const camera: Phaser.Cameras.Scene2D.Camera = this.cameras.main;
    camera.postFX.clear();

    if (roomId === 4) {
      this.resetMarbleTreasures();
      // underwater
      const colorMatrix: Phaser.Display.ColorMatrix =
        camera.postFX.addColorMatrix();

      colorMatrix.saturate(-0.1);

      const matrix = colorMatrix.getData();
      matrix[0] *= 0.65;
      matrix[5] *= 0.8;
      matrix[6] *= 0.94;
      matrix[7] *= 1.06;
      matrix[9] += 0.07;
      matrix[10] *= 0.8;
      matrix[11] *= 0.9;
      matrix[12] *= 1.22;
      matrix[14] += 0.1;
      colorMatrix.set(matrix);

      camera.postFX.addGlow(0x00aacc, 2, 0.2, false, 0.1, 6);
    } else {
      // beach, washed out overwhelming light
      const colorMatrix: Phaser.Display.ColorMatrix =
        camera.postFX.addColorMatrix();
      colorMatrix.saturate(0.2);
      colorMatrix.contrast(0.1);

      const matrix = colorMatrix.getData();
      matrix[0] *= 1.1;
      matrix[6] *= 1.11;
      matrix[12] *= 1.15;
      colorMatrix.set(matrix);

      camera.postFX.addGlow(0xffd199, 3, 0.5, false, 0.08, 8);
    }
  };

  protected override enableRoomObjects(roomId: number): void {
    super.enableRoomObjects(roomId);
    // Show water tiles for this room
    this.waterTiles?.showRoom(roomId);
  }

  protected override disableRoomObjects(roomId: number): void {
    // Hide water tiles for this room
    this.waterTiles?.hideRoom(roomId);
    super.disableRoomObjects(roomId);
  }

  protected override registerRoundEvents(): void {
    super.registerRoundEvents();

    EVENT_BUS.addListener(CUSTOM_EVENTS.ROOM_ENTERED, (roomId: number) => {
      this.onEnterRoom(roomId);
    });
    this.onEnterRoom(this.currentRoomId);

    EVENT_BUS.on(
      CUSTOM_EVENTS.START_FISHING_MINI_GAME,
      this.handleFishingMiniGameStart,
      this,
    );
    EVENT_BUS.on(
      CUSTOM_EVENTS.FISHING_MINI_GAME_COMPLETE,
      this.handleFishingMiniGameComplete,
      this,
    );
    EVENT_BUS.on(CUSTOM_EVENTS.DIALOG_START, this.handleDialogStart, this);
    EVENT_BUS.on(
      CUSTOM_EVENTS.DIALOG_COMPLETE,
      this.handleDialogComplete,
      this,
    );
  }

  protected override unregisterRoundEvents(): void {
    EVENT_BUS.off(
      CUSTOM_EVENTS.START_FISHING_MINI_GAME,
      this.handleFishingMiniGameStart,
      this,
    );
    EVENT_BUS.off(
      CUSTOM_EVENTS.FISHING_MINI_GAME_COMPLETE,
      this.handleFishingMiniGameComplete,
      this,
    );
    EVENT_BUS.off(CUSTOM_EVENTS.DIALOG_START, this.handleDialogStart, this);
    EVENT_BUS.off(
      CUSTOM_EVENTS.DIALOG_COMPLETE,
      this.handleDialogComplete,
      this,
    );
  }

  private handleFishingMiniGameStart = (): void => {
    if (this.isFishingMiniGameActive) {
      return;
    }
    const controls = this.playerObject.controls;
    controls.isMovementLocked = true;
    controls.movementControlsLocked = true;
    controls.infoKeyLocked = true;
    controls.reset();
    this.isFishingMiniGameActive = true;
  };

  private handleFishingMiniGameComplete = (data?: {
    success: boolean;
    message?: string;
  }): void => {
    if (!this.isFishingMiniGameActive) {
      return;
    }

    const controls = this.playerObject.controls;
    controls.reset();
    controls.isMovementLocked = false;
    controls.movementControlsLocked = false;
    controls.infoKeyLocked = false;
    this.isFishingMiniGameActive = false;
    if (controls instanceof Keyboard) {
      controls.resetDialogKeys();
    }

    if (!data?.message) {
      return;
    }

    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [data.message],
      choices: [],
    });
  };

  private handleDialogStart = (): void => {
    // We don't want players to die while in dialog in the underwater game,
    // so we pause the world.
    if (this.dataManager.data.currentArea.roomId === 4) {
      this.rooms[
        this.dataManager.data.currentArea.roomId
      ].monGroup?.children.iterate((obj) => {
        const fishObj = obj as Fish;
        fishObj.setActive(false);
        fishObj.physicsBody.setEnable(false);
        return true;
      });
      // lock player movement
      const controls = this.playerObject.controls;
      controls.isMovementLocked = true;
      controls.reset();
    }
  };

  private handleDialogComplete = (): void => {
    if (this.dataManager.data.currentArea.roomId === 4) {
      this.rooms[
        this.dataManager.data.currentArea.roomId
      ].monGroup?.children.iterate((obj) => {
        const fishObj = obj as Fish;
        fishObj.setActive(true);
        fishObj.physicsBody.setEnable(true);
        return true;
      });
    }
    // unlock player movement
    const controls = this.playerObject.controls;
    controls.isMovementLocked = false;
  };
}
