import * as Phaser from "phaser";
import { DEFAULT_UI_TEXT_STYLE } from "../../common/constants";
import { SCENE_KEYS } from "../scene-keys";
import type { FishingMiniGameId } from "./mini-game-registry";

const DIFFICULTY_OPTIONS = [{ label: "Start Fishing" }] as const;

type FishingDifficultySceneStartData = {
  storyFlag?: string;
  miniGameId?: FishingMiniGameId;
};

export class FishingDifficultyScene extends Phaser.Scene {
  #startData?: FishingDifficultySceneStartData;
  #overlay?: Phaser.GameObjects.Graphics;
  #instructionsText?: Phaser.GameObjects.Text;
  #optionTexts: Phaser.GameObjects.Text[] = [];
  #optionContainer?: Phaser.GameObjects.Container;
  #selectedIndex = 0;

  constructor() {
    super({ key: SCENE_KEYS.FISHING_DIFFICULTY_SCENE });
  }

  public init(data?: FishingDifficultySceneStartData): void {
    this.#startData = data;
    this.#selectedIndex = 0;
  }

  public create(): void {
    const camera = this.cameras.main;
    const width = camera.displayWidth;
    const height = camera.displayHeight;

    this.#overlay = this.add.graphics();
    this.#overlay.fillStyle(0x000000, 0.7);
    this.#overlay.fillRect(0, 0, width, height);
    this.#overlay.setDepth(999);

    this.#instructionsText = this.add
      .text(width / 2, height / 2 - 140, "Need a hand?", {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "32px",
        fontFamily: "monospace",
        color: "#FFFFFF",
      })
      .setOrigin(0.5, 0.5)
      .setDepth(1000);

    const container = this.add
      .container(width / 2, height / 2 + 20)
      .setDepth(1000);
    this.#optionContainer = container;

    this.#optionTexts = DIFFICULTY_OPTIONS.map((option, index) => {
      const text = this.add
        .text(0, index * 48, option.label, {
          ...DEFAULT_UI_TEXT_STYLE,
          fontSize: "28px",
          color: "#FFFFFF",
        })
        .setOrigin(0.5, 0.5)
        .setDepth(1000);
      container.add(text);
      return text;
    });

    this.#updateSelection();

    this.input.keyboard?.on("keydown", this.#handleKey, this);

    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.input.keyboard?.off("keydown", this.#handleKey, this);
      this.#cleanup();
    });
  }

  #handleKey = (event: KeyboardEvent): void => {
    const key = event.key;
    const lower = key.toLowerCase();
    const isUp = key === "ArrowUp" || lower === "w";
    const isDown = key === "ArrowDown" || lower === "s";

    if (isUp || isDown) {
      event.preventDefault();
      const delta = isUp ? -1 : 1;
      this.#selectedIndex =
        (this.#selectedIndex + delta + DIFFICULTY_OPTIONS.length) %
        DIFFICULTY_OPTIONS.length;
      this.#updateSelection();
      return;
    }

    if (key === "Enter") {
      event.preventDefault();
      this.#confirmSelection();
      return;
    }

    if (key === "Escape") {
      event.preventDefault();
      this.#selectStandardMode();
    }
  };

  #updateSelection(): void {
    this.#optionTexts.forEach((text, index) => {
      const option = DIFFICULTY_OPTIONS[index];
      const isSelected = index === this.#selectedIndex;
      const prefix = isSelected ? "▶ " : "  ";
      text.setText(`${prefix}${option.label}`);
      text.setColor(isSelected ? "#6eeb83" : "#FFFFFF");
    });
  }

  #confirmSelection(): void {
    this.#startMiniGame();
  }

  #selectStandardMode(): void {
    this.#startMiniGame();
  }

  #startMiniGame(): void {
    const startData = this.#startData ?? {};

    this.scene.launch(SCENE_KEYS.FISHING_MINI_GAME_SCENE, {
      ...startData,
    });
    this.scene.stop();
  }

  #cleanup(): void {
    this.#overlay?.destroy();
    this.#overlay = undefined;
    this.#instructionsText?.destroy();
    this.#instructionsText = undefined;
    this.#optionTexts.forEach((text) => {
      text.destroy();
    });
    this.#optionTexts = [];
    this.#optionContainer?.destroy();
    this.#optionContainer = undefined;
  }
}
