import { parse as parseEmoji } from "@twemoji/parser";
import * as Phaser from "phaser";
import { ASSET_KEYS, FISHED_FISH_FRAME_MAP } from "../../common/assets";
import { ENABLE_DEBUG } from "../../common/config";
import { DEFAULT_UI_TEXT_STYLE } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import { logGameworldEventAsync } from "../../utils";
import { SCENE_KEYS } from "../scene-keys";
import { incrementFishingMiniGameFailureCount } from "./failure-tracker";
import {
  getFishingMiniGameDefinition,
  listFishingMiniGameDefinitions,
  resetMiniGameQuestionPools,
  type FishingMiniGameDefinition,
  type FishingMiniGameId,
  type FishingMiniGameProgressBounds,
  type FishingMiniGameQuestion,
} from "./mini-game-registry";
import { createMorseQuestionDisplay } from "./mini-games/word-encodings";

const COLON_SPACING = 25;
const DEFAULT_PROGRESS_BOUNDS: FishingMiniGameProgressBounds = {
  caught: 0,
  start: 30,
  escaped: 60,
} as const;

const DEFAULT_SCORING_CONFIG = {
  correctDelta: 6,
  incorrectDelta: 3,
  timerDelayMs: 1000,
  timerProgressDelta: 1,
} as const;

// Adaptive easing knobs (per session, not persisted), all time-based:
// - maxAssist: cap on easing multiplier applied to deltas (0=no assist, 1.0=100% more delta for correct answers)
// - timeWithoutProgressMs: time interval in milliseconds between each ease step trigger
// - timeAssistStep: assist increment added each time-based trigger fires
const ADAPTIVE_DIFFICULTY_CONFIG = {
  maxAssist: 1.5,
  timeWithoutProgressMs: 10000,
  timeAssistStep: 0.05,
} as const;

// Bar configuration constants
const BAR_CONFIG = {
  WIDTH_RATIO: 0.8,
  HEIGHT: 40,
  Y_OFFSET: 60,
  FISH_Y_OFFSET: 18,
  FISH_SCALE: 1,
} as const;

const INPUT_CONFIG = {
  WIDTH_RATIO: 0.8,
  HEIGHT: 64,
  Y_OFFSET: 330,
  MAX_LENGTH: 32,
  PLACEHOLDER: "Press Enter to submit",
} as const;

const ALLOWED_INPUT_PATTERN = /^[a-zA-Z0-9 ]$/;

const GAME_INIT_DELAY_MS = 50;

// Mapping from story flags to puzzle info for fishing spots
const SHORE_STORY_FLAG_TO_PUZZLE: Record<
  string,
  { slug: string; title: string }
> = {
  shore_01: { slug: "mechanical_soft_diet", title: "Mechanical Soft Diet" },
  shore_02: { slug: "somebody", title: "Somebody" },
  shore_03: {
    slug: "do_they_have_chemistry",
    title: "Do They Have Chemistry?",
  },
  shore_04: {
    slug: "this_puzzle_has_been_here_the_whole_time",
    title: "This Puzzle Has Been Here The Whole Time",
  },
  shore_05: { slug: "urban_angst", title: "Urban Angst" },
  shore_06: { slug: "crossloop", title: "Crossloop" },
  shore_07: {
    slug: "drop_star_from_teams",
    title: "Drop Star From Teams",
  },
} as const;

type ResolvedScoringConfig = {
  correctDelta: number;
  incorrectDelta: number;
  timerDelayMs: number;
  timerProgressDelta: number;
  progressBounds: FishingMiniGameProgressBounds;
};

type FishingMiniGameStartData = {
  storyFlag?: string;
  miniGameId?: FishingMiniGameId;
  // Deprecated: easy mode is no longer used because difficulty adapts automatically.
  isEasyMode?: boolean;
  isReplay?: boolean;
};

type ImageSequenceQuestionContent = Extract<
  FishingMiniGameQuestion["content"],
  { type: "image-sequence" }
>;
type TextQuestionContent = Extract<
  FishingMiniGameQuestion["content"],
  { type: "text" }
>;

type AdaptiveDifficultyState = {
  assistLevel: number;
  nextTimeEaseMs: number;
  sessionStartMs: number;
  easeStepsAwarded: number;
};

export class FishingMiniGameScene extends Phaser.Scene {
  #progressBar!: Phaser.GameObjects.Graphics;
  #progressBarBg!: Phaser.GameObjects.Graphics;
  #overlay!: Phaser.GameObjects.Graphics;
  #debugAnswerText?: Phaser.GameObjects.Text;
  #debugAdaptiveText?: Phaser.GameObjects.Text;
  #inputDisplay?: Phaser.GameObjects.Text;
  #feedbackText?: Phaser.GameObjects.Text;
  #instructionsText?: Phaser.GameObjects.Text;
  #fishSprite?: Phaser.GameObjects.Sprite;
  #questionDisplay?: Phaser.GameObjects.GameObject;
  #inputValue = "";
  #inputBackground?: Phaser.GameObjects.Rectangle;

  #fishPosition: number = DEFAULT_PROGRESS_BOUNDS.start;
  #timerEvent?: Phaser.Time.TimerEvent;
  #isComplete = false;
  #gameStartTime = 0;
  #basePosition = 0;
  #storyFlag?: string;
  #miniGameId?: FishingMiniGameId;
  #isReplay = false;
  #currentQuestion?: FishingMiniGameQuestion;
  #miniGameDefinition: FishingMiniGameDefinition =
    getFishingMiniGameDefinition();
  #sessionAssistBase = 0;
  #baseScoringConfig: ResolvedScoringConfig = this.#resolveScoringConfig(
    this.#miniGameDefinition,
  );
  #adaptiveDifficultyState: AdaptiveDifficultyState = {
    assistLevel: 0,
    nextTimeEaseMs: 0,
    sessionStartMs: 0,
    easeStepsAwarded: 0,
  };
  #scoringConfig: ResolvedScoringConfig = this.#applyAdaptiveDifficulty(
    this.#baseScoringConfig,
  );

  constructor() {
    super({
      key: SCENE_KEYS.FISHING_MINI_GAME_SCENE,
    });
  }

  public preload(): void {
    listFishingMiniGameDefinitions().forEach((definition) => {
      definition.preload?.(this);
    });
  }

  public init(data?: FishingMiniGameStartData): void {
    // Ensure camera is visible and set up
    this.cameras.main.setVisible(true);
    // Store story flag from scene data
    this.#storyFlag = data?.storyFlag;
    this.#miniGameId = data?.miniGameId;
    this.#isReplay = data?.isReplay ?? false;
    this.#setMiniGameDefinition(data?.miniGameId);
  }

  public create(): void {
    const camera = this.cameras.main;
    const width = camera.displayWidth;
    const height = camera.displayHeight;

    // Create semi-transparent overlay
    this.#overlay = this.add.graphics();
    this.#overlay.fillStyle(0x000000, 0.7);
    this.#overlay.fillRect(0, 0, width, height);
    this.#overlay.setDepth(999);

    // Create word text (centered)
    this.#instructionsText = this.add
      .text(
        width / 2,
        height / 2 - 140,
        this.#miniGameDefinition.instructions,
        {
          ...DEFAULT_UI_TEXT_STYLE,
          fontSize: "28px",
          fontFamily: "monospace",
          color: "#FFFFFF",
        },
      )
      .setOrigin(0.5, 0.5)
      .setDepth(1000)
      .setVisible(true);
    this.#updateInstructionsText();
    if (ENABLE_DEBUG) {
      this.#debugAnswerText = this.add
        .text(width / 2, 40, "", {
          ...DEFAULT_UI_TEXT_STYLE,
          fontSize: "18px",
          fontFamily: "monospace",
          color: "#6eeb83",
        })
        .setOrigin(0.5, 0)
        .setDepth(1002)
        .setVisible(false);
      this.#debugAdaptiveText = this.add
        .text(width / 2, 16, "", {
          ...DEFAULT_UI_TEXT_STYLE,
          fontSize: "14px",
          fontFamily: "monospace",
          color: "#8fd0ff",
        })
        .setOrigin(0.5, 0)
        .setDepth(1002)
        .setVisible(true);
    }

    const inputWidth = width * INPUT_CONFIG.WIDTH_RATIO;
    const inputX = width / 2;
    const inputY = INPUT_CONFIG.Y_OFFSET;

    this.#inputBackground = this.add
      .rectangle(inputX, inputY, inputWidth, INPUT_CONFIG.HEIGHT, 0x000000, 0.4)
      .setOrigin(0.5, 0.5)
      .setStrokeStyle(2, 0xffffff, 0.8)
      .setDepth(1000);

    this.#inputDisplay = this.add
      .text(inputX, inputY, "", {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "16px",
        color: "#FFFFFF",
      })
      .setOrigin(0.5, 0.5)
      .setDepth(1001)
      .setVisible(true);

    this.#feedbackText = this.add
      .text(width / 2, inputY + 60, "", {
        ...DEFAULT_UI_TEXT_STYLE,
        fontSize: "16px",
        fontFamily: "monospace",
        color: "#FFFFFF",
      })
      .setOrigin(0.5, 0.5)
      .setDepth(1001)
      .setVisible(false);

    // Create progress bar background (at bottom)
    const { barX, barY, barWidth, barHeight } = this.#getBarDimensions();

    this.#progressBarBg = this.add.graphics();
    this.#progressBarBg.fillStyle(0x333333);
    this.#progressBarBg.fillRect(barX, barY, barWidth, barHeight);
    this.#progressBarBg.setDepth(1000);

    // Create progress bar fill
    this.#progressBar = this.add.graphics();
    this.#progressBar.setDepth(1001);

    // Create fish sprite on top of the fishing bar
    this.#createFishSprite(barX, barY, barWidth);

    this.input.keyboard?.on("keydown", this.#handleTextInput, this);

    // Register event listener for starting the game (for restarts)
    EVENT_BUS.on(
      CUSTOM_EVENTS.START_FISHING_MINI_GAME as string,
      this.#handleStartGame,
      this,
    );

    // Start the game immediately when scene is created
    // Use a small delay to ensure all UI elements are set up
    this.time.delayedCall(GAME_INIT_DELAY_MS, () => {
      this.#startGame();
    });

    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      EVENT_BUS.off(
        CUSTOM_EVENTS.START_FISHING_MINI_GAME as string,
        this.#handleStartGame,
        this,
      );
      this.#cleanup();
    });
  }

  #setMiniGameDefinition(miniGameId?: FishingMiniGameId): void {
    this.#miniGameDefinition = getFishingMiniGameDefinition(miniGameId);
    this.#updateScoringConfig();
    this.#destroyQuestionDisplay();
    this.#currentQuestion = undefined;
    this.#updateInstructionsText();
    this.#updateInputDisplay();
    this.#updateDebugAnswerText();
    this.#updateAdaptiveDebugText();
  }

  #updateScoringConfig(): void {
    this.#baseScoringConfig = this.#resolveScoringConfig(
      this.#miniGameDefinition,
    );
    this.#recomputeScoringConfig();
  }

  #resolveScoringConfig(
    definition?: FishingMiniGameDefinition,
  ): ResolvedScoringConfig {
    const scoring = definition?.scoring ?? {};
    const boundsOverride = scoring.progressBounds ?? {};
    const progressBounds: FishingMiniGameProgressBounds = {
      caught: boundsOverride.caught ?? DEFAULT_PROGRESS_BOUNDS.caught,
      start: boundsOverride.start ?? DEFAULT_PROGRESS_BOUNDS.start,
      escaped: boundsOverride.escaped ?? DEFAULT_PROGRESS_BOUNDS.escaped,
    };

    return {
      correctDelta: scoring.correctDelta ?? DEFAULT_SCORING_CONFIG.correctDelta,
      incorrectDelta:
        scoring.incorrectDelta ?? DEFAULT_SCORING_CONFIG.incorrectDelta,
      timerDelayMs: scoring.timerDelayMs ?? DEFAULT_SCORING_CONFIG.timerDelayMs,
      timerProgressDelta:
        scoring.timerProgressDelta ?? DEFAULT_SCORING_CONFIG.timerProgressDelta,
      progressBounds,
    };
  }

  #applyAdaptiveDifficulty(
    baseConfig: ResolvedScoringConfig,
  ): ResolvedScoringConfig {
    const assist = this.#adaptiveDifficultyState.assistLevel;
    if (assist <= 0) {
      return baseConfig;
    }

    const boostedCorrectDelta = Math.max(
      1,
      baseConfig.correctDelta * (1 + assist),
    );

    return {
      ...baseConfig,
      correctDelta: boostedCorrectDelta,
      // Keep incorrect/timer/bounds from the base config to avoid jarring jumps.
      timerDelayMs: baseConfig.timerDelayMs,
      incorrectDelta: baseConfig.incorrectDelta,
      timerProgressDelta: baseConfig.timerProgressDelta,
      progressBounds: baseConfig.progressBounds,
    };
  }

  #recomputeScoringConfig(): void {
    this.#scoringConfig = this.#applyAdaptiveDifficulty(
      this.#baseScoringConfig,
    );
    this.#updateAdaptiveDebugText();
  }

  #updateInstructionsText(): void {
    if (!this.#instructionsText) {
      return;
    }

    this.#instructionsText.setText(this.#miniGameDefinition.instructions);
  }

  #getInputPlaceholder(): string {
    return (
      this.#miniGameDefinition.inputPlaceholder ?? INPUT_CONFIG.PLACEHOLDER
    );
  }

  #handleStartGame = (data?: FishingMiniGameStartData): void => {
    // Update story flag if provided in event data
    if (data?.storyFlag !== undefined) {
      this.#storyFlag = data.storyFlag;
      // Update fish sprite if it exists
      if (this.#fishSprite) {
        this.#updateFishSprite();
      }
    }
    if (data?.miniGameId) {
      this.#setMiniGameDefinition(data.miniGameId);
    }
    if (data?.isReplay !== undefined) {
      this.#isReplay = data.isReplay;
    }
    this.#startGame();
  };

  #createFishSprite(barX: number, barY: number, barWidth: number): void {
    const { x, y } = this.#getFishPosition(barX, barY, barWidth);

    const frameName =
      (this.#storyFlag && FISHED_FISH_FRAME_MAP[this.#storyFlag]) ||
      "fished_one";

    this.#fishSprite = this.add.sprite(x, y, ASSET_KEYS.FISHED_FISH, frameName);
    this.#fishSprite.setOrigin(0.5, 0.5);
    this.#fishSprite.setScale(BAR_CONFIG.FISH_SCALE, BAR_CONFIG.FISH_SCALE);
    this.#fishSprite.setDepth(1001);
  }

  #getFishPosition(
    barX: number,
    barY: number,
    barWidth: number,
  ): {
    x: number;
    y: number;
  } {
    const { progressBounds } = this.#scoringConfig;
    const range = Math.max(progressBounds.escaped - progressBounds.caught, 1);
    const positionRatio = Phaser.Math.Clamp(
      (this.#fishPosition - progressBounds.caught) / range,
      0,
      1,
    );
    return {
      x: barX + positionRatio * barWidth,
      y: barY - BAR_CONFIG.FISH_Y_OFFSET,
    };
  }

  #updateFishSprite(): void {
    if (!this.#fishSprite) {
      return;
    }

    const frameName =
      (this.#storyFlag && FISHED_FISH_FRAME_MAP[this.#storyFlag]) ||
      "fished_one";

    this.#fishSprite.setFrame(frameName);
  }

  #startGame = (): void => {
    this.#isComplete = false;
    this.#resetAdaptiveDifficultyForAttempt();
    this.#recomputeScoringConfig();
    this.#clearFeedback();
    this.#showInputBackground();
    this.#updateInstructionsText();
    this.#updateInputDisplay();

    resetMiniGameQuestionPools(this);
    this.#fishPosition = this.#clampProgress(
      this.#scoringConfig.progressBounds.start,
    );

    // Reset timer tracking
    this.#gameStartTime = 0;
    this.#basePosition = this.#scoringConfig.progressBounds.start;

    this.#resetInput();
    this.#selectNewQuestion();
    this.#updateDisplay();
    this.#startTimer();
    this.#updateAdaptiveDebugText();
  };

  #resetAdaptiveDifficultyForAttempt(): void {
    const startAssist = Phaser.Math.Clamp(
      this.#sessionAssistBase,
      0,
      ADAPTIVE_DIFFICULTY_CONFIG.maxAssist,
    );
    this.#adaptiveDifficultyState.assistLevel = startAssist;
    this.#adaptiveDifficultyState.easeStepsAwarded = 0;
    this.#adaptiveDifficultyState.sessionStartMs = this.time.now;
    this.#scheduleNextTimeEase();
    this.#updateAdaptiveDebugText();
  }

  #scheduleNextTimeEase(): void {
    if (
      this.#adaptiveDifficultyState.assistLevel >=
      ADAPTIVE_DIFFICULTY_CONFIG.maxAssist
    ) {
      this.#adaptiveDifficultyState.nextTimeEaseMs = Number.POSITIVE_INFINITY;
      return;
    }

    const nextStepIndex = this.#adaptiveDifficultyState.easeStepsAwarded + 1;
    this.#adaptiveDifficultyState.nextTimeEaseMs =
      this.#adaptiveDifficultyState.sessionStartMs +
      nextStepIndex * ADAPTIVE_DIFFICULTY_CONFIG.timeWithoutProgressMs;
  }

  #noteProgressMade(): void {
    this.#updateAdaptiveDebugText();
  }

  #maybeEaseDifficultyForTime(): void {
    const nextTimeEaseMs = this.#adaptiveDifficultyState.nextTimeEaseMs;
    if (nextTimeEaseMs === 0) {
      return;
    }

    const now = this.time.now;
    if (now >= nextTimeEaseMs) {
      this.#easeDifficulty();
    }
  }

  #easeDifficulty(): void {
    const assistIncrease = ADAPTIVE_DIFFICULTY_CONFIG.timeAssistStep;
    const nextAssist = Phaser.Math.Clamp(
      this.#adaptiveDifficultyState.assistLevel + assistIncrease,
      0,
      ADAPTIVE_DIFFICULTY_CONFIG.maxAssist,
    );

    if (nextAssist === this.#adaptiveDifficultyState.assistLevel) {
      this.#adaptiveDifficultyState.nextTimeEaseMs = Number.POSITIVE_INFINITY;
      this.#updateAdaptiveDebugText();
      return;
    }

    this.#adaptiveDifficultyState.assistLevel = nextAssist;
    this.#adaptiveDifficultyState.easeStepsAwarded += 1;
    this.#scheduleNextTimeEase();
    this.#recomputeScoringConfig();
    this.#updateAdaptiveDebugText();
  }

  #selectNewQuestion(): void {
    this.#currentQuestion = this.#miniGameDefinition.getNextQuestion(this);
    this.#renderQuestion();
  }

  #showInputBackground(): void {
    if (this.#inputBackground) {
      this.#inputBackground.setVisible(true);
    }
    this.#inputDisplay?.setVisible(true);
  }

  #renderQuestion(): void {
    if (!this.#currentQuestion) {
      return;
    }

    this.#destroyQuestionDisplay();

    const camera = this.cameras.main;
    const width = camera.displayWidth;
    const height = camera.displayHeight;
    const questionY = height / 2 - 20;

    const { content } = this.#currentQuestion;

    if (content.type === "image") {
      const image = this.add
        .image(width / 2, questionY, content.textureKey)
        .setOrigin(0.5, 0.5)
        .setDepth(1000);

      const maxWidth = width * (content.maxWidthRatio ?? 0.35);
      const maxHeight = content.maxHeight ?? 180;
      const scale = Math.min(
        maxWidth / image.width,
        maxHeight / image.height,
        1,
      );
      image.setScale(scale);
      this.#questionDisplay = image;
    } else if (content.type === "image-sequence") {
      const container = this.#createImageSequenceDisplay(
        content,
        width / 2,
        questionY,
        width,
      );
      this.#questionDisplay = container;
    } else if (content.type === "morse") {
      const container = createMorseQuestionDisplay(
        this,
        content,
        width / 2,
        questionY,
        width,
      );
      this.#questionDisplay = container;
    } else if (content.type === "text") {
      if (content.hasEmoji) {
        const canvasDisplay = this.#createCanvasTextDisplay(
          content,
          width / 2,
          questionY,
        );
        this.#questionDisplay = canvasDisplay;
      } else {
        const textObject = this.add
          .text(width / 2, questionY, content.text, {
            ...DEFAULT_UI_TEXT_STYLE,
            fontSize: "32px",
            fontFamily: "monospace",
            color: "#FFFFFF",
            ...(content.style ?? {}),
          })
          .setOrigin(0.5, 0.5)
          .setDepth(1000);
        if (content.maxWidthRatio) {
          const maxWidth = width * content.maxWidthRatio;
          textObject.setWordWrapWidth(maxWidth, true);
          textObject.setAlign("center");
        }
        this.#questionDisplay = textObject;
      }
    }

    this.#updateDebugAnswerText();
  }

  #updateDebugAnswerText(): void {
    if (!this.#debugAnswerText) {
      return;
    }

    const answers = this.#currentQuestion?.answers;
    if (!answers || answers.length === 0) {
      this.#debugAnswerText.setVisible(false);
      return;
    }

    this.#debugAnswerText.setText(`Answer: ${answers.join(", ")}`);
    this.#debugAnswerText.setVisible(true);
  }

  #updateAdaptiveDebugText(): void {
    if (!this.#debugAdaptiveText) {
      return;
    }

    const { assistLevel } = this.#adaptiveDifficultyState;
    const { correctDelta, incorrectDelta, timerProgressDelta } =
      this.#scoringConfig;

    const text = [
      `assist=${assistLevel.toFixed(2)}/${ADAPTIVE_DIFFICULTY_CONFIG.maxAssist}`,
      `deltas c:${correctDelta.toFixed(2)} i:${incorrectDelta.toFixed(2)} t:${timerProgressDelta.toFixed(2)}`,
    ].join(" | ");

    this.#debugAdaptiveText.setText(text);
    this.#debugAdaptiveText.setVisible(true);
  }

  #destroyQuestionDisplay(): void {
    if (!this.#questionDisplay) {
      return;
    }

    if (this.#questionDisplay instanceof Phaser.GameObjects.Container) {
      this.#questionDisplay.destroy(true);
    } else {
      this.#questionDisplay.destroy();
    }
    this.#questionDisplay = undefined;
  }

  #createCanvasTextDisplay(
    content: TextQuestionContent,
    centerX: number,
    y: number,
  ): Phaser.GameObjects.Container {
    const container = this.add
      .container(centerX, y)
      .setDepth(1000) as Phaser.GameObjects.Container;

    const style = content.style ?? {};
    const resolvedFontSize = this.#resolveFontSize(style.fontSize);
    const resolvedColor =
      typeof style.color === "string" ? style.color : "#FFFFFF";

    // Parse emojis and create mixed text/image elements
    this.#buildEmojiCanvasElements(
      container,
      content.text,
      resolvedFontSize.numeric,
      resolvedColor,
      style,
    );

    return container;
  }

  #buildEmojiCanvasElements(
    container: Phaser.GameObjects.Container,
    text: string,
    fontSize: number,
    color: string,
    style: Partial<Phaser.Types.GameObjects.Text.TextStyle>,
  ): void {
    const emojis = parseEmoji(text);

    // Process text with emojis
    let lastIndex = 0;
    const elements: {
      element: Phaser.GameObjects.Image | Phaser.GameObjects.Text;
      width: number;
      text?: string;
    }[] = [];

    for (const emoji of emojis) {
      // Add text before emoji
      if (emoji.indices[0] > lastIndex) {
        const textPart = text.slice(lastIndex, emoji.indices[0]);
        const textObject = this.add
          .text(0, 0, textPart, {
            ...DEFAULT_UI_TEXT_STYLE,
            fontSize: `${fontSize}px`,
            fontFamily: style.fontFamily ?? "monospace",
            color: color,
            fontStyle: style.fontStyle ?? "",
          })
          .setOrigin(0, 0.5);

        elements.push({
          element: textObject,
          width: textObject.width,
          text: textPart,
        });
      }

      // Add emoji as preloaded image
      const textureKey = `emoji_${emoji.url.split("/").pop()?.split(".")[0]}`;
      const emojiImage = this.add
        .image(0, 0, textureKey)
        .setOrigin(0, 0.5)
        .setDisplaySize(fontSize, fontSize);
      elements.push({ element: emojiImage, width: fontSize });

      lastIndex = emoji.indices[1];
    }

    // Add remaining text
    if (lastIndex < text.length) {
      const textPart = text.slice(lastIndex);
      const textObject = this.add
        .text(0, 0, textPart, {
          ...DEFAULT_UI_TEXT_STYLE,
          fontSize: `${fontSize}px`,
          fontFamily: style.fontFamily ?? "monospace",
          color: color,
          fontStyle: style.fontStyle ?? "",
        })
        .setOrigin(0, 0.5);

      elements.push({
        element: textObject,
        width: textObject.width,
        text: textPart,
      });
    }

    const totalWidth = elements.reduce((sum, el) => {
      let spacing = 2;
      if (el.text === ":") {
        spacing = COLON_SPACING;
      }

      return sum + el.width + spacing;
    }, -2);
    let x = -totalWidth / 2;

    elements.forEach((el) => {
      el.element.setPosition(x, 0);
      container.add(el.element);
      let spacing = 2;
      if (el.text === ":") {
        spacing = COLON_SPACING;
      }
      x += el.width + spacing;
    });
  }

  #resolveFontSize(
    fontSize?: Phaser.Types.GameObjects.Text.TextStyle["fontSize"],
  ): { css: string; numeric: number } {
    if (typeof fontSize === "number") {
      return { css: `${fontSize}px`, numeric: fontSize };
    }

    if (typeof fontSize === "string" && fontSize.trim().length > 0) {
      const numeric = parseInt(fontSize.replace(/[^\d.]/g, ""), 10);
      return {
        css: fontSize,
        numeric: Number.isFinite(numeric) ? numeric : 32,
      };
    }

    return { css: "32px", numeric: 32 };
  }

  #createImageSequenceDisplay(
    content: ImageSequenceQuestionContent,
    centerX: number,
    y: number,
    screenWidth: number,
  ): Phaser.GameObjects.Container {
    const container = this.add
      .container(centerX, y)
      .setDepth(1000) as Phaser.GameObjects.Container;

    const count = content.textureKeys.length;
    if (count === 0) {
      return container;
    }

    const baseItemSize = content.itemSize ?? 96;
    const baseSpacing = content.spacing ?? 12;
    const basePadding = content.backgroundPadding ?? 12;
    const baseItemSpan = baseItemSize + basePadding * 2;
    const baseTotalWidth = count * baseItemSpan + (count - 1) * baseSpacing;
    const maxWidth = screenWidth * (content.maxWidthRatio ?? 0.85);
    const scale =
      baseTotalWidth > maxWidth && baseTotalWidth > 0
        ? maxWidth / baseTotalWidth
        : 1;
    const itemSize = baseItemSize * scale;
    const spacing = baseSpacing * scale;
    const padding = basePadding * scale;
    const itemSpan = itemSize + padding * 2;
    const totalWidth = count * itemSpan + (count - 1) * spacing;
    const startX = -totalWidth / 2 + itemSpan / 2;
    const backgroundColor = content.backgroundColor ?? 0xffffff;

    content.textureKeys.forEach((textureKey, index) => {
      const x = startX + index * (itemSpan + spacing);
      const background = this.add
        .rectangle(0, 0, itemSpan, itemSpan, backgroundColor)
        .setOrigin(0.5, 0.5);
      background.setStrokeStyle(2, 0x000000, 0.15);
      background.setPosition(x, 0);
      container.add(background);

      const image = this.add.image(0, 0, textureKey).setOrigin(0.5, 0.5);
      image.setDisplaySize(itemSize, itemSize);
      image.setPosition(x, 0);
      container.add(image);
    });

    return container;
  }

  #clampProgress(value: number): number {
    const bounds = this.#scoringConfig.progressBounds;
    return Phaser.Math.Clamp(value, bounds.caught, bounds.escaped);
  }

  #resetInput(): void {
    this.#inputValue = "";
    this.#updateInputDisplay();
  }

  #updateInputDisplay(): void {
    if (!this.#inputDisplay) {
      return;
    }
    const hasValue = this.#inputValue.length > 0;
    const placeholder = this.#getInputPlaceholder();
    this.#inputDisplay.setText(hasValue ? this.#inputValue : placeholder);
    this.#inputDisplay.setAlpha(hasValue ? 1 : 0.6);
  }

  #clearFeedback(): void {
    this.#setFeedback("");
  }

  #setFeedback(message: string, color = "#FFFFFF"): void {
    if (!this.#feedbackText) {
      return;
    }

    this.#feedbackText.setText(message);
    this.#feedbackText.setColor(color);
    this.#feedbackText.setVisible(message.length > 0);
  }

  #handleTextInput = (event: KeyboardEvent): void => {
    if (this.#isComplete) {
      return;
    }

    if (event.key === "Escape") {
      event.preventDefault();
      this.#complete(false);
      return;
    }

    if (event.key === "Enter") {
      event.preventDefault();
      this.#submitInput();
      return;
    }

    if (event.key === "Backspace") {
      event.preventDefault();
      if (this.#inputValue.length > 0) {
        this.#inputValue = this.#inputValue.slice(0, -1);
        this.#updateInputDisplay();
      }
      return;
    }

    if (
      event.key.length === 1 &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      if (!ALLOWED_INPUT_PATTERN.test(event.key)) {
        return;
      }

      event.preventDefault();
      if (this.#inputValue.length >= INPUT_CONFIG.MAX_LENGTH) {
        return;
      }
      this.#inputValue += event.key;
      this.#updateInputDisplay();
    }
  };

  #normalizeAnswer(value: string): string {
    return value
      .toLowerCase()
      .replace(/[^a-z0-9]/gi, "")
      .trim();
  }

  #isCorrectAnswer(guess: string): boolean {
    if (!this.#currentQuestion) {
      return false;
    }

    return this.#currentQuestion.answers.some((answer) => {
      return this.#normalizeAnswer(answer) === this.#normalizeAnswer(guess);
    });
  }

  #submitInput(): void {
    if (this.#isComplete) {
      return;
    }

    // First update position to current elapsed time
    this.#updateFishPositionFromElapsedTime();

    const success = this.#isCorrectAnswer(this.#inputValue);
    const { correctDelta, incorrectDelta, progressBounds } =
      this.#scoringConfig;

    if (success) {
      this.#fishPosition = this.#clampProgress(
        this.#fishPosition - correctDelta,
      );
      this.#noteProgressMade();

      if (this.#fishPosition <= progressBounds.caught) {
        this.#complete(true);
        return;
      }

      // Update base position after correct answer
      this.#updateBasePositionToCurrentPosition();
      this.#resetInput();
      this.#updateDisplay();
      this.#setFeedback("Correct!", "#6eeb83");
      this.#selectNewQuestion();
      return;
    }

    this.#fishPosition = this.#clampProgress(
      this.#fishPosition + incorrectDelta,
    );

    // Update base position after incorrect answer
    this.#updateBasePositionToCurrentPosition();
    this.#resetInput();
    this.#updateDisplay();
    this.#updateAdaptiveDebugText();
    this.#setFeedback("Not quite...", "#ff6b6b");
    this.#selectNewQuestion();

    if (this.#fishPosition >= progressBounds.escaped) {
      this.#complete(false);
    }
  }

  #startTimer(): void {
    // Clear existing timer
    if (this.#timerEvent) {
      this.#timerEvent.destroy();
    }

    // Track real start time and base position
    this.#gameStartTime = performance.now();
    this.#basePosition = this.#fishPosition;

    // Timer increments fish position toward escape
    this.#timerEvent = this.time.addEvent({
      delay: 100,
      callback: this.#handleTimerTick,
      callbackScope: this,
      loop: true,
    });
  }

  #handleTimerTick = (): void => {
    if (this.#isComplete) {
      return;
    }

    this.#maybeEaseDifficultyForTime();
    this.#updateFishPositionFromElapsedTime();
    this.#updateDisplay();

    const { progressBounds } = this.#scoringConfig;
    if (this.#fishPosition >= progressBounds.escaped) {
      this.#complete(false);
    }
  };

  #updateFishPositionFromElapsedTime(): void {
    const now = performance.now();
    const elapsedMs = now - this.#gameStartTime;
    const { timerDelayMs, timerProgressDelta } = this.#scoringConfig;

    // Calculate total timer progress based on elapsed real time
    const totalTimerProgress =
      Math.floor(elapsedMs / timerDelayMs) * timerProgressDelta;

    // Set position to base position plus timer progress
    this.#fishPosition = this.#clampProgress(
      this.#basePosition + totalTimerProgress,
    );
  }

  #updateBasePositionToCurrentPosition(): void {
    // Update the base position to current position and reset timer start
    this.#basePosition = this.#fishPosition;
    this.#gameStartTime = performance.now();
  }

  #getBarDimensions(): {
    barX: number;
    barY: number;
    barWidth: number;
    barHeight: number;
  } {
    const camera = this.cameras.main;
    const width = camera.displayWidth;
    const barWidth = width * BAR_CONFIG.WIDTH_RATIO;
    return {
      barX: width / 2 - barWidth / 2,
      barY: camera.displayHeight - BAR_CONFIG.Y_OFFSET,
      barWidth,
      barHeight: BAR_CONFIG.HEIGHT,
    };
  }

  #updateDisplay(): void {
    if (!this.#progressBar || !this.#progressBarBg) {
      return;
    }

    const { barX, barY, barWidth, barHeight } = this.#getBarDimensions();

    // Update fish sprite position
    if (this.#fishSprite) {
      const { x, y } = this.#getFishPosition(barX, barY, barWidth);
      this.#fishSprite.setPosition(x, y);
    }

    // Redraw progress bar
    this.#progressBar.clear();

    const { progressBounds } = this.#scoringConfig;
    const range = Math.max(progressBounds.escaped - progressBounds.caught, 1);
    const positionRatio = Phaser.Math.Clamp(
      (this.#fishPosition - progressBounds.caught) / range,
      0,
      1,
    );
    const fillWidth = positionRatio * barWidth;

    // Color transitions from green (caught) to red (escaped)
    const green = Math.floor(255 * (1 - positionRatio));
    const red = Math.floor(255 * positionRatio);
    const color = Phaser.Display.Color.GetColor(red, green, 0);

    this.#progressBar.fillStyle(color);
    this.#progressBar.fillRect(barX, barY, fillWidth, barHeight);
  }

  #complete(success: boolean): void {
    if (this.#isComplete) {
      return;
    }

    this.#isComplete = true;
    this.#cleanup();
    let message = "";

    if (!success) {
      incrementFishingMiniGameFailureCount(this.#miniGameId);
      let level = "UNKNOWN";
      try {
        level = getSceneDataManager(this).data.currentArea.level;
      } catch (error) {
        console.warn(
          "Failed to read gameworld level for fishing event:",
          error,
        );
      }

      const data: { mini_game_id?: string; story_flag?: string } = {};
      if (this.#miniGameId) {
        data.mini_game_id = this.#miniGameId;
      }
      if (this.#storyFlag) {
        data.story_flag = this.#storyFlag;
      }

      logGameworldEventAsync({
        type: "fishing_minigame_failure",
        level,
        data: Object.keys(data).length > 0 ? data : undefined,
      });
      this.#sessionAssistBase = Phaser.Math.Clamp(
        this.#sessionAssistBase + ADAPTIVE_DIFFICULTY_CONFIG.timeAssistStep,
        0,
        ADAPTIVE_DIFFICULTY_CONFIG.maxAssist,
      );
      message = "Better luck next time!";
    } else if (success && this.#storyFlag) {
      // Show catch message if fish was caught
      message =
        this.#getCatchMessage(this.#miniGameId, this.#isReplay) ||
        "You caught a fish! Nice work!";
    }

    // Emit result event
    EVENT_BUS.emit(CUSTOM_EVENTS.FISHING_MINI_GAME_COMPLETE, {
      success,
      message,
    });

    // Close the scene
    this.scene.stop();
  }

  #getCatchMessage(
    miniGameId?: FishingMiniGameId,
    isReplay?: boolean,
  ): string | undefined {
    if (!miniGameId) {
      return "You caught a fish! Nice work!";
    }

    // Get puzzle link if we have a story flag
    let puzzleLink = "[b][color=#1d4bbb]puzzle[/color][/b]";
    if (this.#storyFlag) {
      const puzzleInfo = SHORE_STORY_FLAG_TO_PUZZLE[this.#storyFlag];
      if (puzzleInfo) {
        puzzleLink = `[url=/puzzles/${puzzleInfo.slug}][b][color=#801a79]${puzzleInfo.title}[/color][/b][/url]`;
      }
    }

    const messageMap: Record<
      FishingMiniGameId,
      { first: string; replay: string }
    > = {
      "flag-identification": {
        first: `Yarr! That was a fine tug-o-war! As your prize have ${puzzleLink} glub!`,
        replay: `Yarr, ye reeled it in again! Ye already have ${puzzleLink}, but that was a tidy catch!`,
      },
      "arithmetic-practice": {
        first: `Ye sliced through them numbers like a cutlass through kelp, give ${puzzleLink} a try ye clever sea-dog!`,
        replay: `Ye carved through them sums again! ${puzzleLink} be already won, but ye still swung like a seasoned swabbie!`,
      },
      "word-scramble": {
        first: `Ye untangled that word-knot smoother than untanglin' a puzzle from yer beard! Speaking if which - ${puzzleLink} for ye!`,
        replay: `Another word-knot snipped! Ye had ${puzzleLink} already, but ye kept the lines neat as new rope.`,
      },
      "word-encodings": {
        first: `Ye cracked that secret fish cipher—aye, can ye follow it up in ${puzzleLink}!`,
        replay: `Cipher cracked twice over! ${puzzleLink} be in yer pocket already, but the fish salutes yer codecraft.`,
      },
      "wheel-of-fish": {
        first: `Ye nearly spun the wheel off its hinges! Why don't ye give ${puzzleLink} a spin too!`,
        replay: `Ye spun that wheel again without loosin' a spoke! I'd give ye ${puzzleLink} again if I could!`,
      },
      "emoji-riddles": {
        first: `🐟👉🧠💥🎉!${puzzleLink}!`,
        replay: `🐟🔁🧠💥🎉! ${puzzleLink}!`,
      },
      "fish-identification": {
        first: `Sharp eyes, matey! Now feast yer eyes on ${puzzleLink}!`,
        replay: `Sharp eyes twice over! ${puzzleLink} was already yer loot, but ye still pegged that fish true.`,
      },
    };

    const entry = messageMap[miniGameId];
    if (!entry) {
      return undefined;
    }
    return isReplay ? entry.replay : entry.first;
  }

  #cleanup(): void {
    if (this.#timerEvent) {
      this.#timerEvent.destroy();
      this.#timerEvent = undefined;
    }
    if (this.#inputBackground) {
      this.#inputBackground.destroy();
      this.#inputBackground = undefined;
    }
    if (this.#instructionsText) {
      this.#instructionsText.destroy();
      this.#instructionsText = undefined;
    }
    if (this.#fishSprite) {
      this.#fishSprite.destroy();
      this.#fishSprite = undefined;
    }
    if (this.#inputDisplay) {
      this.#inputDisplay.destroy();
      this.#inputDisplay = undefined;
    }
    this.input.keyboard?.off("keydown", this.#handleTextInput, this);

    if (this.#questionDisplay) {
      this.#destroyQuestionDisplay();
    }
    if (this.#feedbackText) {
      this.#feedbackText.destroy();
      this.#feedbackText = undefined;
    }
    if (this.#debugAnswerText) {
      this.#debugAnswerText.destroy();
      this.#debugAnswerText = undefined;
    }
    if (this.#debugAdaptiveText) {
      this.#debugAdaptiveText.destroy();
      this.#debugAdaptiveText = undefined;
    }
  }
}
