import type * as Phaser from "phaser";
import { TILED_LAYER_NAMES } from "../../common/tiled/constants";
import { getTiledRoomObjectsFromMap } from "../../common/tiled/utils";

/**
 * Maps tile IDs to their corresponding animation keys.
 * Each tile ID should map to an animation key that exists in the scene's animations.
 *
 * Example:
 * {
 *   100: "water_tile_1",  // Tile ID 100 uses "water_tile_1" animation
 *   101: "water_tile_2",  // Tile ID 101 uses "water_tile_2" animation
 * }
 */
type WaterTileAnimationMap = Record<number, string>;

type WaterTileSprite = {
  sprite: Phaser.GameObjects.Sprite;
  tileId: number;
  roomId: number;
  x: number;
  y: number;
};

/**
 * Manages animated water tiles by replacing static tiles with animated sprites.
 * All animations are synchronized to start at the same time.
 */
export class WaterTiles {
  #scene: Phaser.Scene;
  #tilemap: Phaser.Tilemaps.Tilemap;
  #waterLayer: Phaser.Tilemaps.TilemapLayer | null = null;
  #tilesetName: string;
  #tilesetAssetKey: string;
  #animationMap: WaterTileAnimationMap;
  #waterSprites: WaterTileSprite[] = [];
  #waterSpritesByRoom = new Map<number, WaterTileSprite[]>();
  #roomObjects: {
    id: number;
    x: number;
    y: number;
    width: number;
    height: number;
  }[] = [];

  constructor(
    scene: Phaser.Scene,
    tilemap: Phaser.Tilemaps.Tilemap,
    tilesetName: string,
    tilesetAssetKey: string,
    animationMap: WaterTileAnimationMap,
  ) {
    this.#scene = scene;
    this.#tilemap = tilemap;
    this.#tilesetName = tilesetName;
    this.#tilesetAssetKey = tilesetAssetKey;
    this.#animationMap = animationMap;
  }

  /**
   * Initializes the water layer and creates animated sprites for all water tiles.
   * Should be called after the tilemap is loaded.
   */
  public initialize(): void {
    // Get room objects for room boundary detection
    const roomLayer = this.#tilemap.getObjectLayer(TILED_LAYER_NAMES.ROOMS);
    if (roomLayer) {
      const rooms = getTiledRoomObjectsFromMap(
        this.#tilemap,
        TILED_LAYER_NAMES.ROOMS,
      );
      this.#roomObjects = rooms.map((room) => ({
        id: room.id,
        x: room.x,
        y: room.y,
        width: room.width,
        height: room.height,
      }));
    }
    // Add tileset if not already added
    const tileset = this.#tilemap.addTilesetImage(
      this.#tilesetName,
      this.#tilesetAssetKey,
    );

    if (!tileset) {
      console.warn(
        `Failed to add water tileset: ${this.#tilesetName} with asset key: ${this.#tilesetAssetKey}`,
      );
      return;
    }

    // Create water layer
    const waterLayer = this.#tilemap.createLayer(
      TILED_LAYER_NAMES.WATER,
      tileset,
      0,
      0,
    );

    if (!waterLayer) {
      console.warn(`Water layer not found in tilemap`);
      return;
    }

    this.#waterLayer = waterLayer;
    this.#waterLayer.setDepth(-2); // In the backest background

    // Hide the original tile layer (we'll replace with sprites)
    this.#waterLayer.setVisible(false);

    // Create animated sprites for all water tiles
    this.#createWaterSprites();
  }

  /**
   * Creates animated sprites for all water tiles in the layer.
   */
  #createWaterSprites(): void {
    if (!this.#waterLayer) {
      return;
    }

    // Iterate through all tiles in the water layer
    this.#waterLayer.forEachTile((tile) => {
      const tileId = tile.index;
      const animationKey = this.#animationMap[tileId];

      // Skip if this tile ID doesn't have an animation mapping
      if (!animationKey) {
        return;
      }

      // Verify animation exists
      if (!this.#scene.anims.exists(animationKey)) {
        console.warn(
          `Water animation key '${animationKey}' does not exist for tile ID ${tileId}`,
        );
        return;
      }

      // Get the animation to find the first frame index
      const anim = this.#scene.anims.get(animationKey);
      if (!anim?.frames?.length) {
        console.warn(
          `Water animation '${animationKey}' has no frames for tile ID ${tileId}`,
        );
        return;
      }

      // Get the first frame index (frames are now numeric: "0", "1", etc.)
      const firstFrame = anim.frames[0];
      const frameKey = firstFrame.frame.name;

      // Calculate world position
      const worldX = tile.pixelX;
      const worldY = tile.pixelY;

      // Determine which room this tile belongs to
      const roomId = this.#getRoomIdForPosition(worldX, worldY);

      // Create sprite at tile position using the first frame of the animation
      const sprite = this.#scene.add.sprite(
        worldX,
        worldY,
        this.#tilesetAssetKey,
        frameKey,
      );

      sprite.setOrigin(0, 0);
      sprite.setDepth(this.#waterLayer?.depth ?? 1);

      const waterTile: WaterTileSprite = {
        sprite,
        tileId,
        roomId,
        x: worldX,
        y: worldY,
      };

      this.#waterSprites.push(waterTile);

      // Group by room for visibility management
      const roomSprites = this.#waterSpritesByRoom.get(roomId) || [];
      roomSprites.push(waterTile);
      this.#waterSpritesByRoom.set(roomId, roomSprites);
    });

    // Start all animations in sync
    this.#startAnimations();
  }

  /**
   * Starts all water animations in sync.
   */
  #startAnimations(): void {
    this.#waterSprites.forEach((waterTile) => {
      const animationKey = this.#animationMap[waterTile.tileId];
      if (animationKey && this.#scene.anims.exists(animationKey)) {
        // Play animation with infinite repeat
        waterTile.sprite.play({
          key: animationKey,
          repeat: -1,
        });
      }
    });
  }

  /**
   * Shows water tiles for a specific room.
   */
  public showRoom(roomId: number): void {
    const roomSprites = this.#waterSpritesByRoom.get(roomId) || [];
    roomSprites.forEach((waterTile) => {
      waterTile.sprite.setVisible(true);
      waterTile.sprite.setActive(true);
    });
  }

  /**
   * Hides water tiles for a specific room.
   */
  public hideRoom(roomId: number): void {
    const roomSprites = this.#waterSpritesByRoom.get(roomId) || [];
    roomSprites.forEach((waterTile) => {
      waterTile.sprite.setVisible(false);
      waterTile.sprite.setActive(false);
    });
  }

  /**
   * Determines which room a position belongs to based on room boundaries.
   */
  #getRoomIdForPosition(x: number, y: number): number {
    // Check each room to see if the position is within its bounds
    for (const room of this.#roomObjects) {
      if (
        x >= room.x &&
        x < room.x + room.width &&
        y >= room.y &&
        y < room.y + room.height
      ) {
        return room.id;
      }
    }

    // Default to room 1 if we can't determine
    console.warn(
      `Could not determine room for water tile at position (${x}, ${y}), defaulting to room 1`,
    );
    return 1;
  }

  /**
   * Cleans up all water sprites.
   */
  public destroy(): void {
    this.#waterSprites.forEach((waterTile) => {
      waterTile.sprite.destroy();
    });
    this.#waterSprites = [];
    this.#waterSpritesByRoom.clear();
  }
}
