import SHORE_EVENTS from "../assets/data/levels/shore/events.json";
import SHORE_NPCS from "../assets/data/levels/shore/npcs.json";
import SHORE_READABLES from "../assets/data/levels/shore/readables.json";
import SHORE_LEVEL from "../assets/data/levels/shore/shore.json";
import SHORE_BACKGROUND from "../assets/data/levels/shore/shore_background.png";
import SHORE_FOREGROUND from "../assets/data/levels/shore/shore_foreground.png";
import BUBBLES_JSON from "../assets/images/effects/bubbles.json";
import BUBBLES_IMG from "../assets/images/effects/bubbles.png";
import BLUEFISH_JSON from "../assets/images/npcs/shore/bluefish.json";
import BLUEFISH_IMG from "../assets/images/npcs/shore/bluefish.png";
import DANGER_TUNA_JSON from "../assets/images/npcs/shore/danger-tuna.json";
import DANGER_TUNA_IMG from "../assets/images/npcs/shore/danger-tuna.png";
import DANGER_YELLOWFISH_JSON from "../assets/images/npcs/shore/danger-yellowfish.json";
import DANGER_YELLOWFISH_IMG from "../assets/images/npcs/shore/danger-yellowfish.png";
import EEL_JSON from "../assets/images/npcs/shore/eel.json";
import EEL_IMG from "../assets/images/npcs/shore/eel.png";
import GREYFISH_JSON from "../assets/images/npcs/shore/greyfish.json";
import GREYFISH_IMG from "../assets/images/npcs/shore/greyfish.png";
import SHARPFISH_JSON from "../assets/images/npcs/shore/sharpfish.json";
import SHARPFISH_IMG from "../assets/images/npcs/shore/sharpfish.png";
import TANFISH_JSON from "../assets/images/npcs/shore/tanfish.json";
import TANFISH_IMG from "../assets/images/npcs/shore/tanfish.png";
import TUNA_JSON from "../assets/images/npcs/shore/tuna.json";
import TUNA_IMG from "../assets/images/npcs/shore/tuna.png";
import YELLOWFISH_JSON from "../assets/images/npcs/shore/yellowfish.json";
import YELLOWFISH_IMG from "../assets/images/npcs/shore/yellowfish.png";
import SANDWATER_JSON from "../assets/images/terrains/sandwater.json";
import SANDWATER_IMG from "../assets/images/terrains/sandwater.png";
import BEACH_BUOY1_JSON from "../assets/images/world_objects/water_objects/beach_buoy1.json";
import BEACH_BUOY1_IMG from "../assets/images/world_objects/water_objects/beach_buoy1.png";
import BEACH_BUOY2_JSON from "../assets/images/world_objects/water_objects/beach_buoy2.json";
import BEACH_BUOY2_IMG from "../assets/images/world_objects/water_objects/beach_buoy2.png";
import DRAGON_FLOAT1_JSON from "../assets/images/world_objects/water_objects/dragon_float1.json";
import DRAGON_FLOAT1_IMG from "../assets/images/world_objects/water_objects/dragon_float1.png";
import FISHING_BOAT1_JSON from "../assets/images/world_objects/water_objects/fishing_boat1.json";
import FISHING_BOAT1_IMG from "../assets/images/world_objects/water_objects/fishing_boat1.png";
import FLOATING_ROCK2_JSON from "../assets/images/world_objects/water_objects/floating_rock2.json";
import FLOATING_ROCK2_IMG from "../assets/images/world_objects/water_objects/floating_rock2.png";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class BubbleCovePreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.BUBBLE_COVE_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadBubbleCoveAssets();
  }

  public create(): void {
    super.create();
    this.#createBubbleCoveAnimations();
  }

  #loadBubbleCoveAssets(): void {
    // Load shore level
    this.load.image(ASSET_KEYS.SHORE_BACKGROUND, SHORE_BACKGROUND);
    this.load.image(ASSET_KEYS.SHORE_FOREGROUND, SHORE_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.SHORE_LEVEL, SHORE_LEVEL);

    // Load fish NPC
    this.load.aseprite(ASSET_KEYS.TUNA, TUNA_IMG, TUNA_JSON);
    this.load.aseprite(ASSET_KEYS.BLUEFISH, BLUEFISH_IMG, BLUEFISH_JSON);
    this.load.aseprite(ASSET_KEYS.EEL, EEL_IMG, EEL_JSON);
    this.load.aseprite(ASSET_KEYS.GREYFISH, GREYFISH_IMG, GREYFISH_JSON);
    this.load.aseprite(ASSET_KEYS.SHARPFISH, SHARPFISH_IMG, SHARPFISH_JSON);
    this.load.aseprite(ASSET_KEYS.TANFISH, TANFISH_IMG, TANFISH_JSON);
    this.load.aseprite(ASSET_KEYS.YELLOWFISH, YELLOWFISH_IMG, YELLOWFISH_JSON);

    // Load enemies
    this.load.aseprite(
      ASSET_KEYS.DANGER_TUNA,
      DANGER_TUNA_IMG,
      DANGER_TUNA_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.DANGER_YELLOWFISH,
      DANGER_YELLOWFISH_IMG,
      DANGER_YELLOWFISH_JSON,
    );

    // Load effects
    this.load.aseprite(ASSET_KEYS.BUBBLES, BUBBLES_IMG, BUBBLES_JSON);

    // Load water tile animations
    this.load.aseprite(ASSET_KEYS.SANDWATER, SANDWATER_IMG, SANDWATER_JSON);

    // Load water objects
    this.load.aseprite(
      ASSET_KEYS.BEACH_BUOY1,
      BEACH_BUOY1_IMG,
      BEACH_BUOY1_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.BEACH_BUOY2,
      BEACH_BUOY2_IMG,
      BEACH_BUOY2_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.DRAGON_FLOAT1,
      DRAGON_FLOAT1_IMG,
      DRAGON_FLOAT1_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.FLOATING_ROCK2,
      FLOATING_ROCK2_IMG,
      FLOATING_ROCK2_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.FISHING_BOAT1,
      FISHING_BOAT1_IMG,
      FISHING_BOAT1_JSON,
    );

    // Load zone-specific data
    this.load.json(ASSET_KEYS.EVENTS, SHORE_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, SHORE_NPCS);
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, SHORE_READABLES);
  }

  #createBubbleCoveAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.TUNA);
    this.anims.createFromAseprite(ASSET_KEYS.BLUEFISH);
    this.anims.createFromAseprite(ASSET_KEYS.DANGER_TUNA);
    this.anims.createFromAseprite(ASSET_KEYS.DANGER_YELLOWFISH);
    this.anims.createFromAseprite(ASSET_KEYS.EEL);
    this.anims.createFromAseprite(ASSET_KEYS.GREYFISH);
    this.anims.createFromAseprite(ASSET_KEYS.SHARPFISH);
    this.anims.createFromAseprite(ASSET_KEYS.TANFISH);
    this.anims.createFromAseprite(ASSET_KEYS.YELLOWFISH);
    this.anims.createFromAseprite(ASSET_KEYS.BUBBLES);
    this.anims.createFromAseprite(ASSET_KEYS.SANDWATER);
    this.anims.createFromAseprite(ASSET_KEYS.BEACH_BUOY1);
    this.anims.createFromAseprite(ASSET_KEYS.BEACH_BUOY2);
    this.anims.createFromAseprite(ASSET_KEYS.DRAGON_FLOAT1);
    this.anims.createFromAseprite(ASSET_KEYS.FLOATING_ROCK2);
    this.anims.createFromAseprite(ASSET_KEYS.FISHING_BOAT1);
  }
}
