import type { FishingMiniGameId } from "./mini-game-registry";

const STORAGE_KEY = "hunt2026_fishing_minigame_failures";
export const EASY_MODE_FAILURE_THRESHOLD = 5;

type FailureMap = Partial<Record<FishingMiniGameId, number>>;

const isBrowser = typeof window !== "undefined";

function readFailureMap(): FailureMap {
  if (!isBrowser) {
    return {};
  }

  try {
    const rawValue = window.localStorage.getItem(STORAGE_KEY);
    if (!rawValue) {
      return {};
    }

    const parsed = JSON.parse(rawValue) as unknown;
    if (typeof parsed !== "object" || parsed === null) {
      return {};
    }

    const map: FailureMap = {};
    Object.entries(parsed).forEach(([key, value]) => {
      if (typeof value === "number" && value >= 0) {
        map[key as FishingMiniGameId] = value;
      }
    });
    return map;
  } catch (error) {
    console.warn("Failed to read fishing mini-game failure map:", error);
    return {};
  }
}

function writeFailureMap(map: FailureMap): void {
  if (!isBrowser) {
    return;
  }

  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(map));
  } catch (error) {
    console.warn("Failed to persist fishing mini-game failure map:", error);
  }
}

export function getFishingMiniGameFailureCount(
  miniGameId: FishingMiniGameId | undefined,
): number {
  if (!miniGameId) {
    return 0;
  }
  const map = readFailureMap();
  return map[miniGameId] ?? 0;
}

export function incrementFishingMiniGameFailureCount(
  miniGameId: FishingMiniGameId | undefined,
): number {
  if (!miniGameId) {
    return 0;
  }

  const map = readFailureMap();
  const nextCount = (map[miniGameId] ?? 0) + 1;
  map[miniGameId] = nextCount;
  writeFailureMap(map);
  return nextCount;
}

export function shouldOfferFishingEasyMode(
  miniGameId: FishingMiniGameId | undefined,
): boolean {
  return (
    miniGameId !== undefined &&
    getFishingMiniGameFailureCount(miniGameId) >= EASY_MODE_FAILURE_THRESHOLD
  );
}
