import { type TeamHuntState } from "@hunt/public-client";
import React, { useCallback } from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadBubbleCoveScenes } from "../gameworld/scene-loaders/bubble_cove";
import BubbleCoveBody from "./BubbleCoveBody";
import BubbleCoveGameManager from "./BubbleCoveGameManager";
import { type BubbleCoveState } from "./types";

const BubbleCoveManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: BubbleCoveState;
  initialTeamState: TeamHuntState;
}) => {
  // Callback to handle deliverable deliveries
  const handleDeliverableDelivered = useCallback((objectId: string) => {
    // Dispatch a custom event that the Phaser game can listen to
    const event = new CustomEvent("bubbleCoveDeliverableDelivered", {
      detail: { objectId },
    });
    window.dispatchEvent(event);
  }, []);

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="bubble_cove"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadBubbleCoveScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <>
              <BubbleCoveGameManager
                onDeliverableDelivered={handleDeliverableDelivered}
              />
              <BubbleCoveBody
                state={state}
                teamState={teamState}
                gameNode={gameNode}
              />
            </>
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("bubble_cove-root");
if (elem) {
  const { initialBubbleCoveState: state, initialTeamState } =
    window as unknown as {
      initialBubbleCoveState: BubbleCoveState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <BubbleCoveManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount BubbleCoveManager because #bubble_cove-root was nowhere to be found",
  );
}
